RootGui.IgnoreGuiInset = false
pcall(function()
    RootGui.ScreenInsets = Enum.ScreenInsets.CoreUISafeInsets
    RootGui.SafeAreaCompatibility = Enum.SafeAreaCompatibility.None
    RootGui.ClipToDeviceSafeArea = true
end)
RootGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
local parented = pcall(function()
    RootGui.Parent = (gethui and gethui()) or CoreGui
end)
if not parented or not RootGui.Parent then RootGui.Parent = LocalPlayer:WaitForChild("PlayerGui") end
Library.RootGui = RootGui

function Library:Unload()
    if self._Unloaded then return end
    self._Unloaded = true
    if self.Window then self.Window.IsFullyClosed = true end
    for _, callback in ipairs(self.UnloadCallbacks) do
        local ok, message = pcall(callback)
        if not ok then warn("[SenZUi cleanup] " .. tostring(message)) end
    end
    for _, connection in ipairs(self.Connections) do
        if connection and connection.Connected then connection:Disconnect() end
    end
    self.Connections = {}
    self.UnloadCallbacks = {}
    RootGui:Destroy()
end

