-- SenZUi controls with mutable callbacks and runtime update handles.
local function senzyInstance(class, parent, properties)
    local object = Instance.new(class)
    for key, value in pairs(properties or {}) do object[key] = value end
    object.Parent = parent
    return object
end

local function senzyRound(object, radius)
    senzyInstance("UICorner", object, {CornerRadius = UDim.new(0, radius or 9)})
end

local function senzyText(parent, text, size, position, dimensions)
    return senzyInstance("TextLabel", parent, {
        BackgroundTransparency = 1, BorderSizePixel = 0, Text = tostring(text or ""),
        Font = Enum.Font.GothamMedium, TextSize = size or 13,
        TextColor3 = Library.Theme.Text_Primary, TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Position = position or UDim2.fromOffset(14, 0), Size = dimensions or UDim2.new(1, -28, 1, 0)
    })
end

local function buildSenzyControls(SecObj, Container, SecHeader, trackedCards, WindowObj)
    local order = 0
    local function base(kind, cfg, height)
        if type(cfg) == "string" then cfg = {Name = cfg} end
        cfg = cfg or {}
        order = order + 1
        local name = cfg.Name or cfg.Text or kind
        local card = senzyInstance("Frame", Container, {
            Name = cfg.Flag or name, Size = UDim2.new(1, 0, 0, height), BorderSizePixel = 0,
            BackgroundColor3 = Library.Theme.BG_Surface, LayoutOrder = order, ClipsDescendants = true
        })
        senzyRound(card, 9)
        local border = senzyInstance("UIStroke", card, {Color = Library.Theme.Border, Thickness = 1, Transparency = 0.5})
        local title = senzyText(card, name, 13)
        local record = {Card = card, Header = SecHeader, Container = Container, Name = name .. " " .. (cfg.Description or "")}
        table.insert(trackedCards, record)
        local handle = {Type = kind, Settings = cfg, Value = nil, Instance = card, Title = title, Flag = cfg.Flag}
        function handle:UpdateName(value)
            self.Settings.Name = tostring(value)
            title.Text = tostring(value)
            record.Name = tostring(value) .. " " .. (self.Settings.Description or "")
        end
        function handle:_Emit(...)
            if Library._Unloaded or type(self.Settings.Callback) ~= "function" then return end
            local success, message = pcall(self.Settings.Callback, ...)
            if not success then
                warn("[SenZUi] " .. tostring(self.Settings.Name) .. ": " .. tostring(message))
                Library:Notify("Action failed", tostring(self.Settings.Name) .. ": " .. tostring(message), 5, "Error")
            end
        end
        function handle:_Commit(value, silent)
            self.Value = value
            if self.Flag then Library.Flags[self.Flag] = value end
            if not silent then self:_Emit(value) end
        end
        function handle:SetVisible(value) card.Visible = value == true end
        card.MouseEnter:Connect(function() border.Transparency = 0.1 end)
        card.MouseLeave:Connect(function() border.Transparency = 0.5 end)
        if cfg.Flag then Library.Options[cfg.Flag] = handle end
        return handle, card, title
    end

    local function overlay(parent)
        return senzyInstance("TextButton", parent, {Name = "Action", Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1, Text = "", AutoButtonColor = false})
    end

    function SecObj:AddButton(cfg)
        local h, card, title = base("Button", cfg, 46)
        title.Size = UDim2.new(1, -58, 1, 0)
        local arrow = senzyText(card, ">", 17, UDim2.new(1, -34, 0, 0), UDim2.fromOffset(20, 46))
        arrow.TextColor3 = Library.Theme.Accent_Main
        table.insert(WindowObj.ThemeUpdateCallbacks, function(c) arrow.TextColor3 = c end)
        local btn = overlay(card)
        function h:Press() self:_Emit() end
        btn.Activated:Connect(function()
            if h._Busy or Library._Unloaded then return end
            h._Busy = true
            card.BackgroundColor3 = Library.Theme.BG_Container
            h:Press()
            if card.Parent then card.BackgroundColor3 = Library.Theme.BG_Surface end
            h._Busy = false
        end)
        h.Button = btn
        return h
    end

    function SecObj:AddToggle(cfg)
        cfg = cfg or {}
        local hasDescription = type(cfg.Description) == "string" and #cfg.Description > 0
        local h, card, title = base("Toggle", cfg, hasDescription and 70 or 50)
        title.Size = UDim2.new(1, -84, 0, hasDescription and 30 or 50)
        if hasDescription then
            local desc = senzyText(card, cfg.Description, 11, UDim2.fromOffset(14, 29), UDim2.new(1, -84, 0, 34))
            desc.TextColor3 = Library.Theme.Text_Dark; desc.TextWrapped = true
        end
        local switch = senzyInstance("Frame", card, {Size = UDim2.fromOffset(42, 22),
            Position = UDim2.new(1, -56, 0.5, -11), BorderSizePixel = 0})
        senzyRound(switch, 11)
        local knob = senzyInstance("Frame", switch, {Size = UDim2.fromOffset(16, 16),
            BackgroundColor3 = Library.Theme.Text_Primary, BorderSizePixel = 0})
        senzyRound(knob, 8)
        function h:SetValue(value, silent)
            value = value == true
            switch.BackgroundColor3 = value and Library.Theme.Accent_Main or Library.Theme.BG_Container
            knob.Position = value and UDim2.new(1, -19, 0.5, -8) or UDim2.new(0, 3, 0.5, -8)
            self:_Commit(value, silent)
        end
        h.Set = h.SetValue; h.Update = h.SetValue
        h:SetValue(cfg.Default, true)
        local btn = overlay(card)
        btn.Activated:Connect(function() h:SetValue(not h.Value) end)
        h.Button = btn
        table.insert(WindowObj.ThemeUpdateCallbacks, function(c) if h.Value then switch.BackgroundColor3 = c end end)
        return h
    end

    function SecObj:AddSlider(cfg)
        cfg = cfg or {}
        local h, card, title = base("Slider", cfg, 78)
        local minimum, maximum = cfg.Min or cfg.Minimum or 0, cfg.Max or cfg.Maximum or 100
        if maximum < minimum then minimum, maximum = maximum, minimum end
        local precision = math.clamp(math.floor(tonumber(cfg.Precision) or 0), 0, 6)
        local factor = 10 ^ precision
        local suffix = cfg.Suffix or (cfg.DisplayMethod == "Percent" and "%" or "")
        title.Size = UDim2.new(1, -132, 0, 36)
        local valueText = senzyInstance("TextBox", card, {Name = "Value", BackgroundColor3 = Library.Theme.BG_Container,
            BorderSizePixel = 0, ClearTextOnFocus = false, Font = Enum.Font.GothamBold, TextSize = 12,
            TextColor3 = Library.Theme.Accent_Main, Size = UDim2.fromOffset(104, 27), Position = UDim2.new(1, -118, 0, 8)})
        senzyRound(valueText, 6)
        local bar = senzyInstance("Frame", card, {Size = UDim2.new(1, -32, 0, 6), Position = UDim2.fromOffset(16, 54),
            BackgroundColor3 = Library.Theme.BG_Container, BorderSizePixel = 0})
        senzyRound(bar, 3)
        local fill = senzyInstance("Frame", bar, {BackgroundColor3 = Library.Theme.Accent_Main, BorderSizePixel = 0})
        senzyRound(fill, 3)
        local knob = senzyInstance("Frame", bar, {Size = UDim2.fromOffset(14, 14),
            BackgroundColor3 = Library.Theme.Text_Primary, BorderSizePixel = 0})
        senzyRound(knob, 7)
        function h:SetValue(value, silent)
            value = tonumber(value)
            if not value or value ~= value then return false end
            value = math.clamp(math.floor(value * factor + 0.5) / factor, minimum, maximum)
            local ratio = maximum == minimum and 0 or (value - minimum) / (maximum - minimum)
            fill.Size = UDim2.new(ratio, 0, 1, 0)
            knob.Position = UDim2.new(ratio, -7, 0.5, -7)
            valueText.Text = string.format("%." .. precision .. "f", value) .. suffix
            self:_Commit(value, silent)
            return true
        end
        h.Set = h.SetValue; h.Update = h.SetValue
        h:SetValue(cfg.Default or minimum, true)
        valueText.FocusLost:Connect(function()
            local value = tonumber(valueText.Text) or tonumber(valueText.Text:match("^%s*([%+%-]?%d*%.?%d+)"))
            if not h:SetValue(value) then h:SetValue(h.Value, true) end
        end)
        local hit = overlay(bar)
        hit.Size = UDim2.new(1, 12, 0, 28); hit.Position = UDim2.fromOffset(-6, -11)
        local dragging = false
        local function update(input)
            local ratio = math.clamp((input.Position.X - bar.AbsolutePosition.X) / math.max(1, bar.AbsoluteSize.X), 0, 1)
            h:SetValue(minimum + ratio * (maximum - minimum))
        end
        hit.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = true; update(input) end
        end)
        Library:Connect(UserInputService.InputChanged, function(input)
            if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then update(input) end
        end)
        Library:Connect(UserInputService.InputEnded, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = false end
        end)
        table.insert(WindowObj.ThemeUpdateCallbacks, function(c) fill.BackgroundColor3 = c; valueText.TextColor3 = c end)
        h.Input = valueText
        return h
    end

    function SecObj:AddDropdown(cfg)
        cfg = cfg or {}
        local multi = cfg.Multi == true
        local h, card, title = base("Dropdown", cfg, 68)
        local options, disabled, selected, rows = {}, {}, {}, {}
        local expanded = false
        title.Position = UDim2.fromOffset(14, 6); title.Size = UDim2.new(1, -52, 0, 24)
        local summary = senzyText(card, "Select...", 12, UDim2.fromOffset(14, 31), UDim2.new(1, -52, 0, 24))
        summary.TextColor3 = Library.Theme.Accent_Main
        local arrow = senzyText(card, "+", 20, UDim2.new(1, -34, 0, 17), UDim2.fromOffset(20, 30))
        local hit = overlay(card); hit.Size = UDim2.new(1, 0, 0, 68)
        local pane = senzyInstance("Frame", card, {Position = UDim2.fromOffset(12, 72), Size = UDim2.new(1, -24, 0, 222), BackgroundTransparency = 1, Visible = false})
        local search = senzyInstance("TextBox", pane, {Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = Library.Theme.BG_Container,
            BorderSizePixel = 0, Text = "", PlaceholderText = "Search options...", ClearTextOnFocus = false, Font = Enum.Font.GothamMedium,
            TextSize = 12, TextColor3 = Library.Theme.Text_Primary, PlaceholderColor3 = Library.Theme.Text_Dark, Visible = cfg.Search ~= false})
        senzyRound(search, 6)
        local searchHeight = cfg.Search == false and 0 or 36
        local scroll = senzyInstance("ScrollingFrame", pane, {Size = UDim2.new(1, 0, 0, 174), Position = UDim2.fromOffset(0, searchHeight),
            BackgroundTransparency = 1, BorderSizePixel = 0, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollBarThickness = 3, ScrollBarImageColor3 = Library.Theme.Accent_Main})
        senzyInstance("UIListLayout", scroll, {Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder})
        local empty = senzyText(scroll, "No options available. Use Refresh to reload.", 11, nil, UDim2.new(1, -20, 0, 40))
        empty.TextWrapped = true; empty.TextColor3 = Library.Theme.Text_Dark
        local function isDisabled(value, index)
            if disabled[value] then return true end
            if index and disabled[index] == true then return true end
            return false
        end
        local function activeArray()
            local a, seen = {}, {}
            for _,v in ipairs(options) do if selected[v] then a[#a+1] = v; seen[v] = true end end
            local pending = {}
            for v,yes in pairs(selected) do if yes and not seen[v] then pending[#pending+1] = v end end
            table.sort(pending)
            for _,v in ipairs(pending) do a[#a+1] = v end
            return a
        end
        local function paint()
            local values = activeArray()
            summary.Text = #values == 0 and "Select..." or table.concat(values, ", ")
            for value,row in pairs(rows) do
                row.Button.BackgroundColor3 = selected[value] and Library.Theme.BG_Container or Library.Theme.BG_Dark
                row.Button.TextColor3 = row.Disabled and Library.Theme.Text_Dark or selected[value] and Library.Theme.Accent_Main or Library.Theme.Text_Secondary
                row.Button.Text = (row.Disabled and "[LOCK] " or selected[value] and "[+] " or "    ") .. value
            end
        end
        local function expand(value)
            expanded = value; pane.Visible = value; arrow.Text = value and "-" or "+"
            card.Size = UDim2.new(1, 0, 0, value and (260 + searchHeight) or 68)
        end
        local function filter()
            local query, count = search.Text:lower(), 0
            for value,row in pairs(rows) do row.Button.Visible = string.find(value:lower(), query, 1, true) ~= nil; if row.Button.Visible then count = count + 1 end end
            empty.Visible = count == 0
            empty.Text = #options == 0 and "No options available. Use Refresh to reload." or "No matching options."
        end
        function h:SetValue(value, silent)
            local nextSelected = {}
            if multi then
                if type(value) == "table" then
                    for key,item in pairs(value) do
                        local v = type(key) == "number" and item or item == true and key or nil
                        if type(v) == "string" and not isDisabled(v) then nextSelected[v] = true end
                    end
                elseif type(value) == "string" and not isDisabled(value) then nextSelected[value] = true end
            else
                if type(value) == "table" then value = value[1] end
                if value ~= nil and value ~= "" then
                    value = tostring(value)
                    if isDisabled(value) then return false end
                    nextSelected[value] = true
                end
            end
            selected = nextSelected
            paint()
            local values = activeArray()
            self:_Commit(multi and values or values[1], silent)
            return true
        end
        h.Set = h.SetValue; h.Select = h.SetValue; h.Update = h.SetValue
        function h:InsertOptions(values, lockMap)
            options = {}; local seen = {}
            for _,v in ipairs(values or {}) do v = tostring(v); if not seen[v] then seen[v] = true; options[#options+1] = v end end
            disabled = {}
            for key,value in pairs(lockMap or {}) do
                if type(key) == "number" and type(value) == "string" then disabled[value] = true
                elseif value then disabled[key] = value end
            end
            self.Settings.Options = options; self.Settings.Disabled = lockMap or {}
            for _,row in pairs(rows) do row.Button:Destroy() end
            rows = {}
            local selectionChanged = false
            for index,value in ipairs(options) do
                local locked = isDisabled(value,index)
                if locked and selected[value] then selected[value] = nil; selectionChanged = true end
                local button = senzyInstance("TextButton", scroll, {Name = value, Size = UDim2.new(1, -8, 0, 34), BorderSizePixel = 0,
                    LayoutOrder = index, Text = value, TextSize = 12, Font = Enum.Font.GothamMedium,
                    TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, AutoButtonColor = not locked})
                senzyRound(button, 5)
                rows[value] = {Button = button, Disabled = locked}
                button.Activated:Connect(function()
                    if locked then return end
                    if multi then
                        selected[value] = not selected[value]
                        h:SetValue(activeArray())
                    else h:SetValue(value); expand(false) end
                end)
            end
            paint(); filter()
            if selectionChanged then local a=activeArray(); self:_Commit(multi and a or a[1], false) end
        end
        h.Refresh = h.InsertOptions; h.UpdateOptions = h.InsertOptions
        search:GetPropertyChangedSignal("Text"):Connect(filter)
        hit.Activated:Connect(function() expand(not expanded) end)
        h:InsertOptions(cfg.Options or {}, cfg.Disabled)
        h:SetValue(cfg.Default, true)
        h.SearchBox = search; h.Button = hit; h.Summary = summary
        table.insert(WindowObj.ThemeUpdateCallbacks, function(c) summary.TextColor3 = c; scroll.ScrollBarImageColor3 = c; paint() end)
        return h
    end

    function SecObj:AddMultiDropdown(cfg)
        cfg = cfg or {}; cfg.Multi = true
        return self:AddDropdown(cfg)
    end

    function SecObj:AddLabel(value)
        local cfg = type(value) == "table" and value or {Name = tostring(value or "")}
        local h, card, title = base("Label", cfg, 46)
        title.TextWrapped = true; title.TextTruncate = Enum.TextTruncate.None
        title.TextColor3 = Library.Theme.Text_Secondary
        h.Set = h.UpdateName; h.SetText = h.UpdateName
        return h
    end

    function SecObj:AddParagraph(title, description)
        local h, card, label = base("Paragraph", {Name = title or "", Description = description or ""}, 94)
        label.Position = UDim2.fromOffset(14, 8); label.Size = UDim2.new(1, -28, 0, 24)
        local desc = senzyText(card, description, 12, UDim2.fromOffset(14, 34), UDim2.new(1, -28, 0, 52))
        desc.TextWrapped = true; desc.TextColor3 = Library.Theme.Text_Dark
        return h
    end

    function SecObj:AddTextbox(cfg)
        cfg = cfg or {}
        local h, card, title = base("Textbox", cfg, 76)
        title.Size = UDim2.new(1, -28, 0, 30)
        local input = senzyInstance("TextBox", card, {Size = UDim2.new(1, -28, 0, 32), Position = UDim2.fromOffset(14, 34),
            Text = cfg.Default or "", PlaceholderText = cfg.Placeholder or "Enter text...", BackgroundColor3 = Library.Theme.BG_Container,
            TextColor3 = Library.Theme.Text_Primary, Font = Enum.Font.GothamMedium, TextSize = 12, ClearTextOnFocus = false, BorderSizePixel = 0})
        senzyRound(input, 6)
        function h:SetValue(value, silent) input.Text = tostring(value or ""); self:_Commit(input.Text, silent) end
        h:SetValue(cfg.Default, true)
        input.FocusLost:Connect(function() h:SetValue(input.Text) end)
        h.Input = input
        return h
    end
end

function Library:CreateWindow(config)
    config = config or {}
    local winTitle = config.Title or "SENZY HUB"
    local winSubtitle = config.Subtitle or "Free Script"

    local savedColor = self:AutoLoadColor()
    fetchLoaderLua(self)

    local WindowObj = {
        CurrentTab = nil,
        Tabs = {},
        TabOrder = {},
        IsMinimized = false,
        IsFullyClosed = false,
        SidebarCollapsed = false,
        SidebarCards = {},
        ThemeUpdateCallbacks = {},
        SidebarWidth = 310,
        IsMobileMode = false
    }

    self.Window = WindowObj
    local ViewportHost = Instance.new("Frame")
    ViewportHost.Name = "SenzySafeViewport"
    ViewportHost.Size = UDim2.fromScale(1, 1)
    ViewportHost.BackgroundTransparency = 1
    ViewportHost.BorderSizePixel = 0
    ViewportHost.Parent = RootGui

    local MainFrame = Instance.new("Frame")
    MainFrame.Name = "MainFrame"
    MainFrame.Size = UDim2.fromOffset(1120, 720)
    MainFrame.Position = UDim2.new(0.5, 0, 0.5, 0)
    MainFrame.AnchorPoint = Vector2.new(0.5, 0.5)
    MainFrame.BackgroundColor3 = self.Theme.BG_Dark
    MainFrame.BorderSizePixel = 0
    MainFrame.ClipsDescendants = true
    MainFrame.Visible = false
    MainFrame.Parent = ViewportHost
    local MainScale = Instance.new("UIScale", MainFrame)
    MainScale.Name = "MobileFitScale"
    MainScale.Scale = 1
    Instance.new("UICorner", MainFrame).CornerRadius = UDim.new(0, 12)

    local MainStroke = Instance.new("UIStroke")
    MainStroke.Color = self.Theme.Border
    MainStroke.Thickness = 1.5
    MainStroke.Parent = MainFrame

    local FloatingWidget = Instance.new("TextButton")
    FloatingWidget.Size = UDim2.fromOffset(54, 54)
    FloatingWidget.Position = UDim2.new(0, 20, 0.5, -27)
    FloatingWidget.BackgroundColor3 = self.Theme.BG_Panel
    FloatingWidget.Text = ""
    FloatingWidget.Visible = false
    FloatingWidget.Parent = ViewportHost
    Instance.new("UICorner", FloatingWidget).CornerRadius = UDim.new(1, 0)
    
    local WidgetStroke = Instance.new("UIStroke")
    WidgetStroke.Color = savedColor
    WidgetStroke.Thickness = 2
    WidgetStroke.Parent = FloatingWidget
    table.insert(WindowObj.ThemeUpdateCallbacks, function(col) WidgetStroke.Color = col end)

    local WidgetLogo = createCachedImage(RAW_LOGO_URL, "SENZY_LOGO_CACHE.png", FloatingWidget)
    WidgetLogo.Size = UDim2.new(0.7, 0, 0.7, 0)
    WidgetLogo.Position = UDim2.new(0.15, 0, 0.15, 0)

    local TopBar = Instance.new("Frame")
    TopBar.Size = UDim2.new(1, 0, 0, 52)
    TopBar.BackgroundColor3 = self.Theme.BG_Panel
    TopBar.BorderSizePixel = 0
    TopBar.Parent = MainFrame
    TopBar.Name = "WindowDragBar"

    local HamburgerBtn = Instance.new("TextButton")
    HamburgerBtn.Size = UDim2.fromOffset(36, 36)
    HamburgerBtn.Position = UDim2.new(0, 10, 0, 8)
    HamburgerBtn.BackgroundColor3 = self.Theme.BG_Surface
    HamburgerBtn.Text = ""
    HamburgerBtn.Parent = TopBar
    Instance.new("UICorner", HamburgerBtn).CornerRadius = UDim.new(0, 6)

    local HamIcon = createHamburgerIcon(HamburgerBtn)
    HamIcon.Position = UDim2.new(0.5, -9, 0.5, -7)

    local HeaderTitleFrame = Instance.new("Frame")
    HeaderTitleFrame.Size = UDim2.new(1, -150, 1, 0)
    HeaderTitleFrame.ClipsDescendants = true
    HeaderTitleFrame.Position = UDim2.new(0, 56, 0, 0)
    HeaderTitleFrame.BackgroundTransparency = 1
    HeaderTitleFrame.Parent = TopBar

    local HeaderTitle = Instance.new("TextLabel")
    HeaderTitle.Size = UDim2.new(1, 0, 0, 22)
    HeaderTitle.Position = UDim2.new(0, 0, 0, 8)
    HeaderTitle.Text = winTitle
    HeaderTitle.TextTruncate = Enum.TextTruncate.AtEnd
    HeaderTitle.Font = Enum.Font.GothamBlack
    HeaderTitle.TextSize = 16
    HeaderTitle.TextColor3 = self.Theme.Text_Primary
    HeaderTitle.TextXAlignment = Enum.TextXAlignment.Left
    HeaderTitle.BackgroundTransparency = 1
    HeaderTitle.Parent = HeaderTitleFrame

    local HeaderSubTitle = Instance.new("TextLabel")
    HeaderSubTitle.Size = UDim2.new(1, 0, 0, 16)
    HeaderSubTitle.Position = UDim2.new(0, 0, 0, 28)
    HeaderSubTitle.Text = winSubtitle
    HeaderSubTitle.TextTruncate = Enum.TextTruncate.AtEnd
    HeaderSubTitle.Font = Enum.Font.GothamBold
    HeaderSubTitle.TextSize = 10
    HeaderSubTitle.TextColor3 = savedColor
    HeaderSubTitle.TextXAlignment = Enum.TextXAlignment.Left
    HeaderSubTitle.BackgroundTransparency = 1
    HeaderSubTitle.Parent = HeaderTitleFrame
    table.insert(WindowObj.ThemeUpdateCallbacks, function(col) HeaderSubTitle.TextColor3 = col end)

    local WindowControls = Instance.new("Frame")
    WindowControls.Size = UDim2.new(0, 80, 1, 0)
    WindowControls.Position = UDim2.new(1, -85, 0, 0)
    WindowControls.BackgroundTransparency = 1
    WindowControls.Parent = TopBar

    local MinimizeBtn = Instance.new("TextButton")
    MinimizeBtn.Size = UDim2.new(0, 32, 0, 32)
    MinimizeBtn.Position = UDim2.new(0, 4, 0.5, -16)
    MinimizeBtn.BackgroundColor3 = self.Theme.BG_Surface
    MinimizeBtn.Text = ""
    MinimizeBtn.Parent = WindowControls
    Instance.new("UICorner", MinimizeBtn).CornerRadius = UDim.new(0, 6)

    local MinIcon = Instance.new("Frame")
    MinIcon.Size = UDim2.new(0, 10, 0, 2)
    MinIcon.Position = UDim2.new(0.5, -5, 0.5, -1)
    MinIcon.BackgroundColor3 = self.Theme.Text_Secondary
    MinIcon.Parent = MinimizeBtn

    local CloseBtn = Instance.new("TextButton")
    CloseBtn.Size = UDim2.new(0, 32, 0, 32)
    CloseBtn.Position = UDim2.new(0, 42, 0.5, -16)
    CloseBtn.BackgroundColor3 = self.Theme.BG_Surface
    CloseBtn.Text = ""
    CloseBtn.Parent = WindowControls
    Instance.new("UICorner", CloseBtn).CornerRadius = UDim.new(0, 6)

    local CloseX1 = Instance.new("Frame")
    CloseX1.Size = UDim2.new(0, 12, 0, 2)
    CloseX1.Position = UDim2.new(0.5, -6, 0.5, -1)
    CloseX1.Rotation = 45
    CloseX1.BackgroundColor3 = self.Theme.Accent_Dark
    CloseX1.Parent = CloseBtn

    local CloseX2 = Instance.new("Frame")
    CloseX2.Size = UDim2.new(0, 12, 0, 2)
    CloseX2.Position = UDim2.new(0.5, -6, 0.5, -1)
    CloseX2.Rotation = -45
    CloseX2.BackgroundColor3 = self.Theme.Accent_Dark
    CloseX2.Parent = CloseBtn

    local dragging, dragStart, startPos
    TopBar.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true dragStart = input.Position startPos = MainFrame.Position
        end
    end)
    TopBar.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = false end
    end)
    table.insert(self.Connections, Library:Connect(UserInputService.InputChanged, function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local delta = input.Position - dragStart
            local nextPosition = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
            MainFrame.Position = WindowObj._ClampPosition and WindowObj._ClampPosition(nextPosition) or nextPosition
        end
    end))

    local function setMinimizeState(minimize)
        WindowObj.IsMinimized = minimize
        if minimize then
            MainFrame.Visible = false FloatingWidget.Visible = true
        else
            FloatingWidget.Visible = false MainFrame.Visible = true
        end
    end

    MinimizeBtn.Activated:Connect(function() setMinimizeState(true) end)
    FloatingWidget.Activated:Connect(function() setMinimizeState(false) end)

    CloseBtn.Activated:Connect(function() Library:Unload() end)

    table.insert(self.Connections, Library:Connect(UserInputService.InputBegan, function(input, gpe)
        if not gpe and not WindowObj.CapturingKey and not UserInputService:GetFocusedTextBox() and input.KeyCode == Library.Keybinds.ToggleUI then
            setMinimizeState(not WindowObj.IsMinimized)
        end
    end))

    local Sidebar = Instance.new("Frame")
    Sidebar.Name = "Sidebar"
    Sidebar.Size = UDim2.new(0, 310, 1, -52)
