    local function updateAccentTheme(newColor)
        Library.Theme.Accent_Main = newColor
        Library.Theme.Accent_Hover = newColor:Lerp(Color3.new(1, 1, 1), 0.12)
        Library.Theme.Accent_Glow = newColor:Lerp(Color3.new(1, 1, 1), 0.3)
        Library.Theme.Accent_Dark = newColor:Lerp(Color3.new(0, 0, 0), 0.18)
        Library:AutoSaveColor(newColor)
        for _, cb in ipairs(WindowObj.ThemeUpdateCallbacks) do
            pcall(cb, newColor)
        end
    end

    -- Size against the ScreenGui's safe content rectangle, not raw device pixels.
    local function availableViewport()
        local measured = ViewportHost.AbsoluteSize
        if measured.X > 0 and measured.Y > 0 then return measured end
        local camera = Workspace.CurrentCamera or Camera
        local size = camera and camera.ViewportSize or Vector2.new(1280, 800)
        local ok, topLeft, bottomRight = pcall(function() return GuiService:GetGuiInset() end)
        if ok and topLeft and bottomRight then
            return Vector2.new(math.max(1, size.X - topLeft.X - bottomRight.X),
                math.max(1, size.Y - topLeft.Y - bottomRight.Y))
        end
        return size
    end

    local function layoutSidebar()
        local open = not WindowObj.SidebarCollapsed
        local width = WindowObj.SidebarWidth or 270
        Sidebar.Visible = open
        Sidebar.Size = UDim2.new(0, open and width or 0, 1, -52)
        Sidebar.ZIndex = WindowObj.UseDrawer and 6 or 2
        DrawerShade.Visible = WindowObj.UseDrawer and open
        local reserved = open and not WindowObj.UseDrawer and width or 0
        ContentArea.Size = UDim2.new(1, -reserved, 1, -52)
        ContentArea.Position = UDim2.fromOffset(reserved, 52)
    end
    WindowObj._LayoutSidebar = layoutSidebar

    local function clampWindowPosition(position)
        local viewport = availableViewport()
        local rendered = WindowObj.RenderedSize or Vector2.new(1, 1)
        local margin = WindowObj.ScreenMargin or 8
        local centerX = position.X.Scale * viewport.X + position.X.Offset
        local centerY = position.Y.Scale * viewport.Y + position.Y.Offset
        local lowX, lowY = rendered.X / 2 + margin, rendered.Y / 2 + margin
        local highX = math.max(lowX, viewport.X - rendered.X / 2 - margin)
        local highY = math.max(lowY, viewport.Y - rendered.Y / 2 - margin)
        return UDim2.fromOffset(math.clamp(centerX, lowX, highX), math.clamp(centerY, lowY, highY))
    end
    WindowObj._ClampPosition = clampWindowPosition

    local function applyPlatformMode(mode)
        if Library._Unloaded then return end
        mode = mode or WindowObj.RequestedPlatform or "Auto"
        WindowObj.RequestedPlatform = mode
        local viewport = availableViewport()
        -- Touch clients may report MouseEnabled even without a physical mouse.
        local mobile = mode == "MOBILE" or mode == "Auto" and UserInputService.TouchEnabled
        local portrait = viewport.Y > viewport.X
        local margin = mobile and 8 or 12
        margin = math.min(margin, viewport.X / 8, viewport.Y / 8)
        local roomW, roomH = math.max(1, viewport.X - margin * 2), math.max(1, viewport.Y - margin * 2)
        local targetW = mobile and (portrait and 440 or 720) or (config.Width or 1040)
        local targetH = mobile and (portrait and 640 or 440) or (config.Height or 680)
        local desiredW = math.min(targetW, roomW)
        local desiredH = math.min(targetH, roomH)
        -- Keep controls readable; scale the whole panel only for unusually small views.
        local logicalW, logicalH = math.max(320, desiredW), math.max(240, desiredH)
        local scale = math.min(1, roomW / logicalW, roomH / logicalH)
        MainScale.Scale = scale
        MainFrame.Size = UDim2.fromOffset(logicalW, logicalH)
        WindowObj.RenderedSize = Vector2.new(logicalW * scale, logicalH * scale)
        WindowObj.ScreenMargin = margin
        WindowObj.IsMobileMode = mobile
        WindowObj.IsPortrait = portrait
        local drawer = mobile or logicalW < 760
        if WindowObj.UseDrawer ~= drawer then WindowObj.SidebarCollapsed = drawer end
        WindowObj.UseDrawer = drawer
        WindowObj.SidebarWidth = drawer and math.min(280, logicalW - 48) or 270
        layoutSidebar()

        HeaderTitle.TextSize = mobile and 14 or 16
        HeaderTitleFrame.Size = UDim2.new(1, mobile and -166 or -150, 1, 0)
        HamburgerBtn.Size = UDim2.fromOffset(mobile and 42 or 36, mobile and 42 or 36)
        HamburgerBtn.Position = UDim2.fromOffset(mobile and 6 or 10, mobile and 5 or 8)
        WindowControls.Size = UDim2.new(0, mobile and 96 or 80, 1, 0)
        WindowControls.Position = UDim2.new(1, mobile and -101 or -85, 0, 0)
        MinimizeBtn.Size = UDim2.fromOffset(mobile and 42 or 32, mobile and 42 or 32)
        CloseBtn.Size = MinimizeBtn.Size
        MinimizeBtn.Position = UDim2.new(0, 4, 0.5, mobile and -21 or -16)
        CloseBtn.Position = UDim2.new(0, mobile and 50 or 42, 0.5, mobile and -21 or -16)
        FloatingWidget.Size = UDim2.fromOffset(mobile and 48 or 54, mobile and 48 or 54)
        FloatingWidget.Position = UDim2.new(0, margin, 0.5, mobile and -24 or -27)
        -- Recenter after rotations and viewport changes, including after dragging.
        MainFrame.Position = clampWindowPosition(UDim2.fromScale(0.5, 0.5))
        MainFrame.Visible = not WindowObj.IsMinimized
        WindowObj.MainFrame = MainFrame
        WindowObj.ViewportHost = ViewportHost
        WindowObj.UIScale = MainScale
    end

    WindowObj._ApplyPlatformMode = applyPlatformMode

    function WindowObj:CreateTab(tabConfig)
        tabConfig = type(tabConfig) == "string" and {Name = tabConfig} or tabConfig or {}
        local tabName = tabConfig.Name or "Tab"
        if self.Tabs[tabName] then return self.Tabs[tabName] end
        local isSettings = tabConfig.IsSettings or false
        local TabObj = {Name = tabName, Sections = {}}
        self.Tabs[tabName] = TabObj
        table.insert(self.TabOrder, tabName)

        local NavBtn = Instance.new("TextButton")
        NavBtn.Size = UDim2.new(0, 100, 0, 40)
        NavBtn.BackgroundColor3 = Library.Theme.BG_Surface
        NavBtn.Text = tabName
        NavBtn.Font = Enum.Font.GothamBlack
        NavBtn.TextSize = 11
        NavBtn.TextColor3 = Library.Theme.Text_Secondary
        NavBtn.LayoutOrder = isSettings and 9999 or #WindowObj.TabOrder
        NavBtn.Name = "Tab_" .. tabName
        NavBtn.Parent = TopNav
        Instance.new("UICorner", NavBtn).CornerRadius = UDim.new(0, 6)

        local PageScroll = Instance.new("ScrollingFrame")
        PageScroll.Name = "Page_" .. tabName
        TabObj.Page = PageScroll
        TabObj.Button = NavBtn
        PageScroll.Size = UDim2.new(1, 0, 1, 0)
        PageScroll.BackgroundTransparency = 1
        PageScroll.ScrollBarThickness = 3
        PageScroll.ScrollBarImageColor3 = Library.Theme.Accent_Main
        PageScroll.Visible = false
        PageScroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
        PageScroll.CanvasSize = UDim2.new(0, 0, 0, 0)
        PageScroll.Parent = PageContainer
        table.insert(WindowObj.ThemeUpdateCallbacks, function(col) PageScroll.ScrollBarImageColor3 = col end)

        local PageList = Instance.new("UIListLayout")
        PageList.SortOrder = Enum.SortOrder.LayoutOrder
        PageList.Padding = UDim.new(0, 14)
        PageList.Parent = PageScroll

        local PagePad = Instance.new("UIPadding")
        PagePad.PaddingTop = UDim.new(0, 14)
        PagePad.PaddingLeft = UDim.new(0, 12)
        PagePad.PaddingRight = UDim.new(0, 12)
        PagePad.PaddingBottom = UDim.new(0, 14)
        PagePad.Parent = PageScroll

        local SearchFrame = Instance.new("Frame")
        SearchFrame.Size = UDim2.new(1, 0, 0, 36)
        SearchFrame.LayoutOrder = -1
        SearchFrame.BackgroundColor3 = Library.Theme.BG_Surface
        SearchFrame.Parent = PageScroll
        Instance.new("UICorner", SearchFrame).CornerRadius = UDim.new(0, 8)

        local SearchIcon = Instance.new("TextLabel")
        SearchIcon.Size = UDim2.new(0, 65, 1, 0)
        SearchIcon.Text = "[SEARCH]"
        SearchIcon.Font = Enum.Font.GothamBold
        SearchIcon.TextSize = 9
        SearchIcon.TextColor3 = Library.Theme.Text_Dark
        SearchIcon.BackgroundTransparency = 1
        SearchIcon.Parent = SearchFrame

        local SearchBox = Instance.new("TextBox")
        SearchBox.Size = UDim2.new(1, -75, 1, 0)
        SearchBox.Position = UDim2.new(0, 68, 0, 0)
        SearchBox.PlaceholderText = "Search features or components..."
        SearchBox.Text = ""
        SearchBox.Font = Enum.Font.GothamMedium
        SearchBox.TextSize = 11
        SearchBox.TextColor3 = Library.Theme.Text_Primary
        SearchBox.PlaceholderColor3 = Library.Theme.Text_Dark
        SearchBox.TextXAlignment = Enum.TextXAlignment.Left
        SearchBox.BackgroundTransparency = 1
        SearchBox.Parent = SearchFrame

        local trackedCards = {}

        TabObj.SearchBox = SearchBox
        SearchBox:GetPropertyChangedSignal("Text"):Connect(function()
            local query, headers, containers = SearchBox.Text:lower(), {}, {}
            for _, item in ipairs(trackedCards) do
                local match = query == "" or string.find(item.Name:lower(), query, 1, true) ~= nil
                item.Card.Visible = match
                if item.Header then headers[item.Header] = headers[item.Header] == true or match end
                if item.Container then containers[item.Container] = containers[item.Container] == true or match end
            end
            for header, visible in pairs(headers) do header.Visible = visible end
            for container, visible in pairs(containers) do container.Visible = visible end
        end)

        if WindowObj.CurrentTab == nil then
            WindowObj.CurrentTab = PageScroll
            PageScroll.Visible = true
            NavBtn.BackgroundColor3 = Library.Theme.Accent_Main
            NavBtn.TextColor3 = Library.Theme.Text_Primary
        end

        table.insert(WindowObj.ThemeUpdateCallbacks, function(col)
            if WindowObj.CurrentTab == PageScroll then
                NavBtn.BackgroundColor3 = col
            end
        end)

        function TabObj:Select()
            for _, page in ipairs(PageContainer:GetChildren()) do if page:IsA("ScrollingFrame") then page.Visible = false end end
            for _, button in ipairs(TopNav:GetChildren()) do
                if button:IsA("TextButton") then button.BackgroundColor3 = Library.Theme.BG_Surface; button.TextColor3 = Library.Theme.Text_Secondary end
            end
            WindowObj.CurrentTab = PageScroll
            WindowObj.CurrentTabName = tabName
            PageScroll.Visible = true
            NavBtn.BackgroundColor3 = Library.Theme.Accent_Main
            NavBtn.TextColor3 = Library.Theme.Text_Primary
        end
        NavBtn.Activated:Connect(function() TabObj:Select() end)

        function TabObj:AddSection(secTitle)
            secTitle = secTitle or "Section"
            local SecObj = {Name = secTitle}
            table.insert(TabObj.Sections, SecObj)
            local sectionOrder = #TabObj.Sections * 2

            local SecHeader = Instance.new("TextLabel")
            SecHeader.Size = UDim2.new(1, 0, 0, 22)
            SecHeader.Text = secTitle:upper()
            SecHeader.LayoutOrder = sectionOrder
            SecHeader.Font = Enum.Font.GothamBlack
            SecHeader.TextSize = 12
            SecHeader.TextColor3 = Library.Theme.Accent_Glow
            SecHeader.TextXAlignment = Enum.TextXAlignment.Left
            SecHeader.BackgroundTransparency = 1
            SecHeader.Parent = PageScroll
            table.insert(WindowObj.ThemeUpdateCallbacks, function() SecHeader.TextColor3 = Library.Theme.Accent_Glow end)

            local Container = Instance.new("Frame")
            Container.Size = UDim2.new(1, 0, 0, 0)
            Container.LayoutOrder = sectionOrder + 1
            SecObj.Header = SecHeader
            SecObj.Container = Container
            Container.BackgroundTransparency = 1
            Container.Parent = PageScroll

            local Layout = Instance.new("UIListLayout")
            Layout.SortOrder = Enum.SortOrder.LayoutOrder
            Layout.Padding = UDim.new(0, 10)
            Layout.Parent = Container

            Layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
                Container.Size = UDim2.new(1, 0, 0, Layout.AbsoluteContentSize.Y)
            end)

            buildSenzyControls(SecObj, Container, SecHeader, trackedCards, WindowObj)

            function SecObj:AddKeybind(cfg)
                local control = SecObj:AddButton({Name = cfg.Name or "Toggle UI Keybind"})
                local key = cfg.Default or Enum.KeyCode.RightControl
                local connection
                function control:SetValue(value, silent)
                    key = value
                    self.Value = key
                    self:UpdateName((cfg.Name or "Toggle UI Keybind") .. "  [" .. key.Name .. "]")
                    if not silent and cfg.Callback then cfg.Callback(key) end
                end
                control:SetValue(key, true)
                control.Settings.Callback = function()
                    if connection then connection:Disconnect() end
                    control:UpdateName("Press a key...")
                    WindowObj.CapturingKey = true
                    connection = Library:Connect(UserInputService.InputBegan, function(input)
                        if input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode ~= Enum.KeyCode.Unknown then
                            connection:Disconnect(); connection = nil
                            control:SetValue(input.KeyCode)
                            WindowObj.CapturingKey = false
                        end
                    end)
                end
                return control
            end

            function SecObj:AddColorPicker(cfg)
                cfg = cfg or {}
                local name = cfg.Name or "Color Picker"
                local defaultColor = savedColor or cfg.Default or Library.Theme.Accent_Main
                local flag = cfg.Flag or name
                local callback = cfg.Callback or function() end

                Library.Flags[flag] = defaultColor
                local isExpanded = false
                local currColor = defaultColor
                local h, s, v = currColor:ToHSV()

                local Card = Instance.new("Frame")
                Card.Size = UDim2.new(1, 0, 0, 44)
                Card.BackgroundColor3 = Library.Theme.BG_Surface
                Card.ClipsDescendants = true
                Card.Parent = Container
                Instance.new("UICorner", Card).CornerRadius = UDim.new(0, 8)
                table.insert(trackedCards, {Card = Card, Header = SecHeader, Name = name})

                local Txt = Instance.new("TextLabel")
                Txt.Size = UDim2.new(0, 140, 0, 44)
                Txt.Position = UDim2.new(0, 12, 0, 0)
                Txt.Text = name
                Txt.Font = Enum.Font.GothamBold
                Txt.TextSize = 12
                Txt.TextColor3 = Library.Theme.Text_Primary
                Txt.TextXAlignment = Enum.TextXAlignment.Left
                Txt.BackgroundTransparency = 1
                Txt.Parent = Card

                local PreviewTile = Instance.new("Frame")
                PreviewTile.Size = UDim2.new(0, 44, 0, 24)
                PreviewTile.Position = UDim2.new(1, -56, 0, 10)
                PreviewTile.BackgroundColor3 = currColor
                PreviewTile.Parent = Card
                Instance.new("UICorner", PreviewTile).CornerRadius = UDim.new(0, 6)

                local ToggleBtn = Instance.new("TextButton")
                ToggleBtn.Size = UDim2.new(1, 0, 0, 44)
                ToggleBtn.BackgroundTransparency = 1
                ToggleBtn.Text = ""
                ToggleBtn.Parent = Card

                local PickerPanel = Instance.new("Frame")
                PickerPanel.Size = UDim2.new(1, -24, 0, 90)
                PickerPanel.Position = UDim2.new(0, 12, 0, 48)
                PickerPanel.BackgroundTransparency = 1
                PickerPanel.Parent = Card

                local HueBar = Instance.new("Frame")
                HueBar.Size = UDim2.new(1, 0, 0, 16)
                HueBar.Position = UDim2.new(0, 0, 0, 10)
                HueBar.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                HueBar.Parent = PickerPanel
                Instance.new("UICorner", HueBar).CornerRadius = UDim.new(0, 4)

                local HueGrad = Instance.new("UIGradient")
                HueGrad.Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 0, 0)),
                    ColorSequenceKeypoint.new(0.167, Color3.fromRGB(255, 255, 0)),
                    ColorSequenceKeypoint.new(0.333, Color3.fromRGB(0, 255, 0)),
                    ColorSequenceKeypoint.new(0.5, Color3.fromRGB(0, 255, 255)),
                    ColorSequenceKeypoint.new(0.667, Color3.fromRGB(0, 0, 255)),
                    ColorSequenceKeypoint.new(0.833, Color3.fromRGB(255, 0, 255)),
                    ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 0, 0))
                })
                HueGrad.Parent = HueBar

                local HueKnob = Instance.new("Frame")
                HueKnob.Size = UDim2.new(0, 10, 1, 4)
                HueKnob.Position = UDim2.new(h, -5, 0, -2)
                HueKnob.BackgroundColor3 = Library.Theme.Text_Primary
                HueKnob.Parent = HueBar
                Instance.new("UICorner", HueKnob).CornerRadius = UDim.new(0, 2)

                local HueBtn = Instance.new("TextButton")
                HueBtn.Size = UDim2.new(1, 0, 1, 0)
                HueBtn.BackgroundTransparency = 1
                HueBtn.Text = ""
                HueBtn.Parent = HueBar

                local ValBar = Instance.new("Frame")
                ValBar.Size = UDim2.new(1, 0, 0, 16)
                ValBar.Position = UDim2.new(0, 0, 0, 45)
                ValBar.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                ValBar.Parent = PickerPanel
                Instance.new("UICorner", ValBar).CornerRadius = UDim.new(0, 4)

                local ValGrad = Instance.new("UIGradient")
                ValGrad.Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 0, 0)),
                    ColorSequenceKeypoint.new(1, Color3.fromHSV(h, s, 1))
                })
                ValGrad.Parent = ValBar

                local ValKnob = Instance.new("Frame")
                ValKnob.Size = UDim2.new(0, 10, 1, 4)
                ValKnob.Position = UDim2.new(v, -5, 0, -2)
                ValKnob.BackgroundColor3 = Library.Theme.Text_Primary
                ValKnob.Parent = ValBar
                Instance.new("UICorner", ValKnob).CornerRadius = UDim.new(0, 2)

                local ValBtn = Instance.new("TextButton")
                ValBtn.Size = UDim2.new(1, 0, 1, 0)
                ValBtn.BackgroundTransparency = 1
                ValBtn.Text = ""
                ValBtn.Parent = ValBar

                local function updateColor()
                    currColor = Color3.fromHSV(h, s, v)
                    PreviewTile.BackgroundColor3 = currColor
                    ValGrad.Color = ColorSequence.new({
                        ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 0, 0)),
                        ColorSequenceKeypoint.new(1, Color3.fromHSV(h, s, 1))
                    })
                    Library.Flags[flag] = currColor
                    pcall(callback, currColor)
                end

                local slidingHue = false
                HueBtn.InputBegan:Connect(function(inp)
                    if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then slidingHue = true end
                end)

                local slidingVal = false
                ValBtn.InputBegan:Connect(function(inp)
                    if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then slidingVal = true end
                end)

                Library:Connect(UserInputService.InputEnded, function(inp)
                    if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
                        slidingHue = false slidingVal = false
                    end
                end)

                Library:Connect(UserInputService.InputChanged, function(inp)
                    if inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch then
                        if slidingHue then
                            h = math.clamp((inp.Position.X - HueBar.AbsolutePosition.X) / HueBar.AbsoluteSize.X, 0, 1)
                            HueKnob.Position = UDim2.new(h, -5, 0, -2)
                            updateColor()
                        elseif slidingVal then
                            v = math.clamp((inp.Position.X - ValBar.AbsolutePosition.X) / ValBar.AbsoluteSize.X, 0, 1)
                            ValKnob.Position = UDim2.new(v, -5, 0, -2)
                            updateColor()
                        end
                    end
                end)

                ToggleBtn.Activated:Connect(function()
                    isExpanded = not isExpanded
                    local targetHeight = isExpanded and 145 or 44
                    TweenService:Create(Card, TweenInfo.new(0.25, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Size = UDim2.new(1, 0, 0, targetHeight)}):Play()
                end)
            end

            return SecObj
        end
        return TabObj
    end

    local SettingsTab = WindowObj:CreateTab({ Name = "Settings", IsSettings = true })
    local SettingsKeybindSec = SettingsTab:AddSection("Keybind Settings")

    WindowObj.KeybindControl = SettingsKeybindSec:AddKeybind({
        Name = "Toggle UI Keybind",
        Default = Enum.KeyCode.RightControl,
        Callback = function(key)
            Library.Keybinds.ToggleUI = key
            Library:Notify("Keybind Updated", "Toggle UI key set to: " .. key.Name, 3, "Success")
        end
    })

    local SettingsThemeSec = SettingsTab:AddSection("Theme & Customization")

    SettingsThemeSec:AddColorPicker({
        Name = "Primary Accent Color",
        Default = savedColor,
        Flag = "AccentColorPicker",
        Callback = function(newCol)
            updateAccentTheme(newCol)
        end
    })

    if config.Platform == "Auto" then
        applyPlatformMode("Auto")
    elseif config.Platform == "PC" or config.Platform == "MOBILE" then
        applyPlatformMode(config.Platform)
    elseif self._SplashActive then
        self._PendingWindow = WindowObj
    else
        self:ShowPlatformSelector(function(selectedPlatform) applyPlatformMode(selectedPlatform) end)
    end
    local function resizeWindow()
        applyPlatformMode(WindowObj.RequestedPlatform or config.Platform or "Auto")
    end
    Library:Connect(ViewportHost:GetPropertyChangedSignal("AbsoluteSize"), resizeWindow)
    Library:Connect(UserInputService:GetPropertyChangedSignal("TouchEnabled"), resizeWindow)
    local cameraConnection
    local function bindCamera()
        if cameraConnection then cameraConnection:Disconnect() end
        Camera = Workspace.CurrentCamera
        if Camera then cameraConnection = Library:Connect(Camera:GetPropertyChangedSignal("ViewportSize"), resizeWindow) end
        resizeWindow()
    end
    Library:Connect(Workspace:GetPropertyChangedSignal("CurrentCamera"), bindCamera)
    bindCamera()
    task.defer(function() if not Library._Unloaded then resizeWindow() end end)

    return WindowObj
end

return Library
end

-- Connect the original game's UI contract to the supplied SenZUi implementation.
local function createSenzyBridge()
    local shared = (getgenv and getgenv()) or _G
    local previous = shared.SenzyOuwlandUI
    if previous and type(previous.Unload) == "function" then pcall(function() previous:Unload() end) end
    local native = createSenzyUI()
    local bridge = {Options = native.Options, Flags = native.Flags, Tabs = {}, Sections = {}, Controls = {},
        Native = native, ConfigFolder = "SenzyHubConfigs/Ouwland/" .. tostring(game.PlaceId), _LoadedConfigs = {}}
    shared.SenzyOuwlandUI = bridge

    function bridge:Unload()
        native:Unload()
        if shared.SenzyOuwlandUI == self then shared.SenzyOuwlandUI = nil end
    end

    function bridge:SetFolder(_)
        -- Separate Senzy profiles from the original framework's configuration files.
        return self.ConfigFolder
    end

    local function configPath(name)
        name = tostring(name or "auto")
        assert(name:match("^[%w_%-]+$"), "Invalid config name")
        return bridge.ConfigFolder .. "/" .. name .. ".json"
    end

    local function createFolders(path)
        assert(type(writefile) == "function" and type(makefolder) == "function" and type(isfolder) == "function",
            "This environment does not support saving configuration files")
        local current = ""
        for part in path:gmatch("[^/]+") do
            current = current == "" and part or current .. "/" .. part
            if not isfolder(current) then makefolder(current) end
        end
    end

    function bridge:SaveConfig(name)
        if self._Loading then return true end
        createFolders(self.ConfigFolder)
        local data = {Version = 1, Values = {}, UI = {Keybind = native.Keybinds.ToggleUI.Name}}
        for flag, control in pairs(self.Options) do
            if control.Type == "Dropdown" and control.Value == nil then
                data.Values[flag] = ""
            elseif control.Type ~= "Button" and control.Value ~= nil then
                local valueType = type(control.Value)
                if valueType == "boolean" or valueType == "number" or valueType == "string" or valueType == "table" then
                    data.Values[flag] = control.Value
                end
            end
        end
        local json = game:GetService("HttpService"):JSONEncode(data)
        writefile(configPath(name), json)
        return true
    end

    function bridge:LoadConfig(name)
        local path = configPath(name)
        if not (type(readfile) == "function" and type(isfile) == "function" and isfile(path)) then return false end
        local ok, data = pcall(function() return game:GetService("HttpService"):JSONDecode(readfile(path)) end)
        if not ok or type(data) ~= "table" or data.Version ~= 1 or type(data.Values) ~= "table" then
            native:Notify("Config", "The saved profile could not be read.", 5, "Warning")
            return false
        end
        self._Loading = true
        local success, message = pcall(function()
            if type(data.UI) == "table" and type(data.UI.Keybind) == "string" then
                local found, key = pcall(function() return Enum.KeyCode[data.UI.Keybind] end)
                if found and key and key ~= Enum.KeyCode.Unknown then
                    native.Keybinds.ToggleUI = key
                    if native.Window and native.Window.KeybindControl then native.Window.KeybindControl:SetValue(key, true) end
                end
            end
            -- Restore parameters before enabling the routines that consume them.
            for _, togglePass in ipairs({false, true}) do
                for flag, value in pairs(data.Values) do
                    local control = self.Options[flag]
                    if control and control.SetValue and (control.Type == "Toggle") == togglePass then
                        local valid = control.Type == "Toggle" and type(value) == "boolean"
                            or control.Type == "Slider" and type(value) == "number"
                            or control.Type == "Dropdown" and (type(value) == "table" or type(value) == "string")
                            or control.Type == "Textbox" and type(value) == "string"
                        if valid then control:SetValue(value) end
                    end
                end
            end
        end)
        self._Loading = false
        if not success then native:Notify("Config", tostring(message), 5, "Error"); return false end
        self._LoadedConfigs[name or "auto"] = true
        return true
    end

    function bridge:LoadAutoLoadConfig()
        if self._LoadedConfigs.auto then return true end
        return self:LoadConfig("auto")
    end

    function bridge:Window(_config)
        local window = native:CreateWindow({Title = "SENZY HUB", Subtitle = "OUWLAND  /  SLAYER 2",
            Platform = "Auto", Width = 1040, Height = 680})
        local facade = {Native = window}
        bridge.WindowObject = facade
        local tabsByName = {}
        function facade:GetNotificationsState() return native.NotificationsEnabled ~= false end
        function facade:SetNotificationsState(value) native.NotificationsEnabled = value == true end
        function facade:Notify(config)
            config = config or {}
            native:Notify(config.Title or "Senzy", config.Description or config.Content or "", config.Duration, config.Type)
        end
        facade.onUnloaded = function(first, second)
            local callback = type(first) == "function" and first or second
            if type(callback) == "function" then table.insert(native.UnloadCallbacks, callback) end
        end
        function facade:Unload() bridge:Unload() end
        function facade:GlobalSetting(config)
            local settings = window:CreateTab({Name = "Settings", IsSettings = true})
            local section = settings:AddSection("Interface")
            local cfg = {}
            for key,value in pairs(config) do cfg[key] = value end
            cfg.Flag = "SenzyNotifications"
            local handle = section:AddToggle(cfg)
            bridge.Controls[#bridge.Controls+1] = {Tab = "Settings", Section = "Interface", Type = "GlobalSetting", Name = cfg.Name, Flag = cfg.Flag, Handle = handle}
            return handle
        end
        local group = {}
        function group:Tab(config)
            local name = config.Name
            if tabsByName[name] then return tabsByName[name] end
            local nativeTab = window:CreateTab({Name = name, IsSettings = name == "Settings"})
            local tab = {Name = name, Native = nativeTab}
            bridge.Tabs[#bridge.Tabs+1] = tab
            tabsByName[name] = tab
            function tab:Select() nativeTab:Select() end
            function tab:Section(sectionConfig)
                local section = nativeTab:AddSection(sectionConfig.Name)
                local wrapper = {Name = sectionConfig.Name, Side = sectionConfig.Side, Native = section}
                bridge.Sections[#bridge.Sections+1] = {Tab = name, Name = sectionConfig.Name, Side = sectionConfig.Side}
                for _, kind in ipairs({"Toggle", "Slider", "Dropdown", "Button", "Label", "SubLabel"}) do
                    local controlKind = kind
                    wrapper[controlKind] = function(_, configOrText, flag)
                        local cfg = {}
                        if type(configOrText) == "table" then
                            for key,value in pairs(configOrText) do cfg[key] = value end
                        else cfg.Text = tostring(configOrText or "") end
                        cfg.Name = cfg.Name or cfg.Text or controlKind
                        cfg.Flag = flag
                        cfg.Min = cfg.Minimum or cfg.Min
                        cfg.Max = cfg.Maximum or cfg.Max
                        -- The recovered core expects a map of option name -> true.
                        -- Native SenZUi exposes an ordered array for its multiselect.
                        if controlKind == "Dropdown" and cfg.Multi and type(cfg.Callback) == "function" then
                            local originalCallback = cfg.Callback
                            cfg.Callback = function(values)
                                local selection = {}
                                for _, value in ipairs(values or {}) do selection[value] = true end
                                return originalCallback(selection)
                            end
                        end
                        local addMethod = controlKind == "SubLabel" and "AddLabel" or "Add" .. controlKind
